/usr/bin/bash -lc "PYTHONPATH=source python - <<'PY'
import numpy as np
from pyscf.pbc import gto, scf
from pyscf.pbc.tools.pbc import super_cell
from workflow.compare_periodic_representations import load_fixture
f=load_fixture(); n=np.asarray(f['sampling_mesh']);
cell=gto.M(unit=f['unit'],a=f['lattice'],atom=[(s,x) for s,x in f['atoms']],basis=f['basis'],pseudo=f['pseudopotential'],mesh=f['fft_mesh'],verbose=0)
sup=super_cell(cell,n); kpts=cell.make_kpts(n,with_gamma_point=True)

def configure(mf, route):
    if route == 'AFTDF':
        return mf.jk_method('AFTDF')
    if route == 'GDF':
        return mf.density_fit()
    if route == 'MDF':
        return mf.mix_density_fit()
    if route == 'RSDF':
        return mf.rs_density_fit()
    if route == 'RS':
        return mf.jk_method('RS')
    return mf

for route in ('AFTDF',):
    kmf=configure(scf.KRHF(cell,kpts),route); kmf.conv_tol=1e-10; kmf.max_cycle=80
    mf=configure(scf.RHF(sup),route); mf.conv_tol=1e-10; mf.max_cycle=80
    ek=kmf.kernel(); eg=mf.kernel()/np.prod(n)
    print(route, {'k':ek,'g':eg,'diff':abs(ek-eg),'converged':(kmf.converged,mf.converged),'meshes':(list(kmf.with_df.mesh),list(mf.with_df.mesh))})
PY"

